('5-1-hece','[{"id": "5-1-hece-1", "prompt": "“oyun” kelimesinin hecelere doğru ayrılışı hangisidir?", "choices": ["oy-un", "oyu-n", "o-yun"], "answer": "o-yun", "explanation": "“oyun” kelimesi o-yun biçiminde ayrılır; her hecede bir ünlü vardır."}, {"id": "5-1-hece-2", "prompt": "“arkadaş” kelimesinin hecelere doğru ayrılışı hangisidir?", "choices": ["ar-kadaş", "ar-ka-daş", "a-rkadaş"], "answer": "ar-ka-daş", "explanation": "“arkadaş” kelimesi ar-ka-daş biçiminde ayrılır; her hecede bir ünlü vardır."}, {"id": "5-1-hece-3", "prompt": "“uçurtma” kelimesinin hecelere doğru ayrılışı hangisidir?", "choices": ["u-çurt-ma", "u-çurtma", "uç-urtma"], "answer": "u-çurt-ma", "explanation": "“uçurtma” kelimesi u-çurt-ma biçiminde ayrılır; her hecede bir ünlü vardır."}, {"id": "5-1-hece-4", "prompt": "“seksek” kelimesinin hecelere doğru ayrılışı hangisidir?", "choices": ["s-eksek", "se-ksek", "sek-sek"], "answer": "sek-sek", "explanation": "“seksek” kelimesi sek-sek biçiminde ayrılır; her hecede bir ünlü vardır."}, {"id": "5-1-hece-5", "prompt": "“tekerleme” kelimesinin hecelere doğru ayrılışı hangisidir?", "choices": ["te-kerleme", "te-ker-le-me", "t-ekerleme"], "answer": "te-ker-le-me", "explanation": "“tekerleme” kelimesi te-ker-le-me biçiminde ayrılır; her hecede bir ünlü vardır."}, {"id": "5-1-hece-6", "prompt": "“bahçe” kelimesinin hecelere doğru ayrılışı hangisidir?", "choices": ["bah-çe", "b-ahçe", "ba-hçe"], "answer": "bah-çe", "explanation": "“bahçe” kelimesi bah-çe biçiminde ayrılır; her hecede bir ünlü vardır."}, {"id": "5-1-hece-7", "prompt": "“kalem” kelimesinin hecelere doğru ayrılışı hangisidir?", "choices": ["k-alem", "kal-em", "ka-lem"], "answer": "ka-lem", "explanation": "“kalem” kelimesi ka-lem biçiminde ayrılır; her hecede bir ünlü vardır."}, {"id": "5-1-hece-8", "prompt": "“çocuk” kelimesinin hecelere doğru ayrılışı hangisidir?", "choices": ["çoc-uk", "ço-cuk", "ç-ocuk"], "answer": "ço-cuk", "explanation": "“çocuk” kelimesi ço-cuk biçiminde ayrılır; her h