('5-1-nokta','[{"id": "5-1-nokta-1", "prompt": "Buluşma saatini doğru gösteren cümle hangisidir?", "choices": ["Saat 09-30''da bahçedeyiz.", "Saat 09.30''da bahçedeyiz.", "Saat 09/30''da bahçedeyiz."], "answer": "Saat 09.30''da bahçedeyiz.", "explanation": "Saat ile dakika arasına nokta konur."}, {"id": "5-1-nokta-2", "prompt": "Sıra sayısının rakamla doğru yazımı hangisidir?", "choices": ["3. sıradaki oyuncu başladı.", "3 sıradaki oyuncu başladı.", "3, sıradaki oyuncu başladı."], "answer": "3. sıradaki oyuncu başladı.", "explanation": "Rakamdan sonra sıra bildiren nokta, üçüncü anlamını verir."}, {"id": "5-1-nokta-3", "prompt": "Gün, ay ve yıl rakamla yazılırken doğru biçim hangisidir?", "choices": ["14,10,2026", "14:10:2026", "14.10.2026"], "answer": "14.10.2026", "explanation": "Nokta, rakamla gösterilen tarih bölümlerini ayırabilir."}, {"id": "5-1-nokta-4", "prompt": "Tarafsız bir haber cümlesi noktayla bitirilecekse hangi yazım doğrudur?", "choices": ["Oyunumuz birazdan başlayacak;", "Oyunumuz birazdan başlayacak.", "Oyunumuz birazdan başlayacak,"], "answer": "Oyunumuz birazdan başlayacak.", "explanation": "Tamamlanmış haber cümlesi noktayla bitirilebilir."}, {"id": "5-1-nokta-5", "prompt": "Doktor kelimesinin noktalı kısaltması hangisidir?", "choices": ["Dr.", "D.r", "Dr,"], "answer": "Dr.", "explanation": "Doktor kelimesinin kısaltması Dr. biçimindedir."}, {"id": "5-1-nokta-6", "prompt": "İkinci takım anlamını doğru veren biçim hangisidir?", "choices": ["2 takım", "2, takım", "2. takım"], "answer": "2. takım", "explanation": "2. biçimi sıra, 2 takım biçimi ise iki adet takım bildirir."}, {"id": "5-1-nokta-7", "prompt": "Saat gösteriminde noktanın doğru kullanıldığı örnek hangisidir?", "choices": ["Oyun 10-15''te bitecek.", "Oyun 10.15''te bitecek.", "Oyun 10/15''te bitecek."], "answer": "Oyun 10.15''te bitecek.", "explanation": "Saat ve dakikayı ayıran nokta 10.15 biçiminde kullanılır."}, {"id": "5-1-nokta-8", "prompt": "Tamamlanmış duyurunun sonuna uygun işaret eklenmiş seçenek hangisidir?", "choices": ["Kartlar masanın üzerindedir.", "Kartlar masanın üzerindedir,", "Kartlar masanın üzerindedir:"], "answer": "Kartlar masanın üzerindedir.", "explanation": "Duyuru tamamlanmış bir bilgi cümlesidir; sonuna nokta konabilir."}, {"id": "5-1-nokta-9", "prompt": "Genel ağ adresindeki doğru ayırma işareti hangi seçenektedir?", "choices": ["meb,gov,tr", "meb;gov;tr", "meb.gov.tr"], "answer": "meb.gov.tr", "explanation": "Genel ağ adreslerinin bölümlerinde nokta kullanılır."}, {"id": "5-1-nokta-10", "prompt": "Beşinci durak anlamını veren doğru yazım hangisidir?", "choices": ["5, durak", "5. durak", "5 durak"], "answer": "5. durak", "explanation": "Nokta, rakamdan sonra sıra sayısı anlamı oluşturur."}]'::jsonb),
('5-1-kisa-cizgi','[{"id": "5-1-kisa-cizgi-1", "prompt": "Kısa çizgiyle heceleri gösterilen “oyuncak” kelimesinde doğru kullanım hangisidir?", "choices": ["oy-uncak", "o-yun-cak", "o-yuncak"], "answer": "o-yun-cak", "explanation": "Kısa çizgi hece sınırlarına konur: o-yun-cak."}, {"id": "5-1-kisa-cizgi-2", "prompt": "Kısa çizgiyle heceleri gösterilen “pencere” kelimesinde doğru kullanım hangisidir?", "choices": ["pen-ce-re", "p-encere", "pe-ncere"], "answer": "pen-ce-re", "explanation": "Kısa çizgi hece sınırlarına konur: pen-ce-re."}, {"id": "5-1-kisa-cizgi-3", "prompt": "Kısa çizgiyle heceleri gösterilen “çocuk” kelimesinde doğru kullanım hangisidir?", "choices": ["ç-ocuk", "çoc-uk", "ço-cuk"], "answer": "ço-cuk", "explanation": "Kısa çizgi hece sınırlarına konur: ço-cuk."}, {"id": "5-1-kisa-cizgi-4", "prompt": "Kısa çizgiyle heceleri gösterilen “kalem” kelimesinde doğru kullanım hangisidir?", "choices": ["kal-em", "ka-lem", "k-alem"], "answer": "ka-lem", "explanation": "Kısa çizgi hece sınırlarına konur: ka-lem."}, {"id": "5-1-kisa-cizgi-5", "prompt": "Kısa çizgiyle heceleri gösterilen “bahçe” kelimesinde doğru kullanım hangisidir?", "choices": ["bah-çe", "b-ahçe", "ba-hçe"], "answer": "bah-çe", "explanation": "Kısa çizgi hece sınırlarına konur: bah-çe."}, {"id": "5-1-kisa-cizgi-6", "prompt": "Kısa çizgiyle heceleri gösterilen “tekerleme” kelimesinde doğru kullanım hangisidir?", "choices": ["t-ekerleme", "te-kerleme", "te-ker-le-me"], "answer": "te-ker-le-me", "explanation": "Kısa çizgi hece sınırlarına konur: te-ker-le-me."}, {"id": "5-1-kisa-cizgi-7", "prompt": "Kısa çizgiyle heceleri gösterilen “seksek” kelimesinde doğru kullanım hangisidir?", "choices": ["se-ksek", "sek-sek", "s-eksek"], "answer": "sek-sek", "explanation": "Kısa çizgi hece sınırlarına konur: sek-sek."}, {"id": "5-1-kisa-cizgi-8", "prompt": "Kısa çizgiyle heceleri gösterilen “uçurtma” kelimesinde doğru kullanım hangisidir?", "choices": ["u-çurt-ma", "u-çurtma", "uç-urtma"], "answer": "u-çurt-ma", "explanation": "Kısa çizgi hece sınırlarına konur: u-çurt-ma."}, {"id": "5-1-kisa-cizgi-9", "prompt": "Kısa çizgiyle heceleri gösterilen “arkadaş” kelimesinde doğru kullanım hangisidir?", "choices": ["a-rkadaş", "ar-kadaş", "ar-ka-daş"], "answer": "ar-ka-daş", "explanation": "Kısa çizgi hece sınırlarına konur: ar-ka-daş."}, {"id": "5-1-kisa-cizgi-10", "prompt": "Kısa çizgiyle heceleri gösterilen “oyun” kelimesinde doğru kullanım hangisidir?", "choices": ["oyu-n", "o-yun", "oy-un"], "answer": "o-yun", "explanation": "Kısa çizgi hece sınırlarına konur: o-yun."}]'::jsonb),
('5-1-isim-fiil','[{"id": "5-1-isim-fiil-1", "prompt": "“Çocuk topu bahçeye bıraktı.” cümlesinde “topu” hangi türdedir?", "choices": ["isim", "fiil", "bağlaç"], "answer": "isim", "explanation": "“topu” bu cümlede bir varlık veya kavramı adlandırır."}, {"id": "5-1-isim-fiil-2", "prompt": "“Oyuncu sırayı bekledi.” cümlesinde “bekledi” hangi türdedir?", "choices": ["isim", "bağlaç", "fiil"], "answer": "fiil", "explanation": "“bekledi” bu cümlede gerçekleşen bir işi ya da hareketi bildirir."}, {"id": "5-1-isim-fiil-3", "prompt": "“Mavi kutu masadaydı.” cümlesinde “kutu” hangi türdedir?", "choices": ["bağlaç", "isim", "fiil"], "answer": "isim", "explanation": "“kutu” bu cümlede bir varlık veya kavramı adlandırır."}, {"id": "5-1-isim-fiil-4", "prompt": "“Defne yeni bir oyun tasarladı.” cümlesinde “tasarladı” hangi türdedir?", "choices": ["fiil", "isim", "bağlaç"], "answer": "fiil", "explanation": "“tasarladı” bu cümlede gerçekleşen bir işi ya da hareketi bildirir."}, {"id": "5-1-isim-fiil-5", "prompt": "“Takım bahçede toplandı.” cümlesinde “takım” hangi türdedir?", "choices": ["fiil", "bağlaç", "isim"], "answer": "isim", "explanation": "“takım” bu cümlede bir varlık veya kavramı adlandırır."}, {"id": "5-1-isim-fiil-6", "prompt": "“Ali haritayı katladı.” cümlesinde “katladı” hangi türdedir?", "choices": ["bağlaç", "fiil", "isim"], "answer": "fiil", "explanation": "“katladı” bu cümlede gerçekleşen bir işi ya da hareketi bildirir."}, {"id": "5-1-isim-fiil-7", "prompt": "“Sabır oyunda işe yarar.” cümlesinde “Sabır” hangi türdedir?", "choices": ["isim", "fiil", "bağlaç"], "answer": "isim", "explanation": "“Sabır” bu cümlede bir varlık veya kavramı adlandırır."}, {"id": "5-1-isim-fiil-8", "prompt": "“Çocuklar birlikte güldü.” cümlesinde “güldü” hangi türdedir?", "choices": ["isim", "bağlaç", "fiil"], "answer": "fiil", "explanation": "“güldü” bu cümlede gerçekleşen bir işi ya da hareketi bildirir."}, {"id": "5-1-isim-fiil-9", "prompt": "“Çeşmenin yanında tebeşir vardı.” cümlesinde “tebeşir” hangi türdedir?", "choices": ["bağlaç", "isim", "fiil"], "answer": "isim", "explanation": "“tebeşir” bu cümlede bir varlık veya kavramı adlandırır."}, {"id": "5-1-isim-fiil-10", "prompt": "“Ece arkadaşını dinliyor.” cümlesinde “dinliyor” hangi türdedir?", "choices": ["fiil", "isim", "bağlaç"], "answer": "fiil", "explanation": "“dinliyor” bu cümlede gerçekleşen bir işi ya da hareketi bildirir."}]'::jsonb),
('5-1-tahmin','[{"id": "5-1-tahmin-1", "prompt": "“Galiba yarın yeni bir oyun oynayacağız.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["tahmin", "kesin emir", "gerçekleşmiş olayı kesin bildirme"], "answer": "tahmin", "explanation": "Cümledeki ifade tahmin anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-1-tahmin-2", "prompt": "“Bu izler bir oyuncuya ait olabilir.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["kesin emir", "gerçekleşmiş olayı kesin bildirme", "tahmin"], "answer": "tahmin", "explanation": "Cümledeki ifade tahmin anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-1-tahmin-3", "prompt": "“Herhâlde kartlar kutunun içindedir.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["gerçekleşmiş olayı kesin bildirme", "tahmin", "kesin emir"], "answer": "tahmin", "explanation": "Cümledeki ifade tahmin anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-1-tahmin-4", "prompt": "“Muhtemelen arkadaşımız birazdan gelir.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["tahmin", "kesin emir", "gerçekleşmiş olayı kesin bildirme"], "answer": "tahmin", "explanation": "Cümledeki ifade tahmin anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-1-tahmin-5", "prompt": "“Belki bu ipucu bizi çeşmeye götürür.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["kesin emir", "gerçekleşmiş olayı kesin bildirme", "tahmin"], "answer": "tahmin", "explanation": "Cümledeki ifade tahmin anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-1-tahmin-6", "prompt": "“Bulutlara bakılırsa yağmur yağabilir.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["gerçekleşmiş olayı kesin bildirme", "tahmin", "kesin emir"], "answer": "tahmin", "explanation": "Cümledeki ifade tahmin anlamını kurar; sözün kesinlik düzeyi ve amacı buna g