('5-2-buyuk-harf','[{"id": "5-2-buyuk-harf-1", "prompt": "Normal cümle yazımında özel ad kuralına göre aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["ayşe''nin defteri", "Ayşe’nindefteri", "Ayşe''nin defteri"], "answer": "Ayşe''nin defteri", "explanation": "Kişi, saygı sözü, hayvan özel adı veya ülke adı büyük harfle başlar; ayrı sözcükler birleştirilmez."}, {"id": "5-2-buyuk-harf-2", "prompt": "Normal cümle yazımında özel ad kuralına göre aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["mustafa Kemal Atatürk", "Mustafa Kemal Atatürk", "Mustafa kemal Atatürk"], "answer": "Mustafa Kemal Atatürk", "explanation": "Kişi, saygı sözü, hayvan özel adı veya ülke adı büyük harfle başlar; ayrı sözcükler birleştirilmez."}, {"id": "5-2-buyuk-harf-3", "prompt": "Normal cümle yazımında özel ad kuralına göre aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Deniz Hanım", "Deniz hanım", "deniz Hanım"], "answer": "Deniz Hanım", "explanation": "Kişi, saygı sözü, hayvan özel adı veya ülke adı büyük harfle başlar; ayrı sözcükler birleştirilmez."}, {"id": "5-2-buyuk-harf-4", "prompt": "Normal cümle yazımında özel ad kuralına göre aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Ali bey", "ali Bey", "Ali Bey"], "answer": "Ali Bey", "explanation": "Kişi, saygı sözü, hayvan özel adı veya ülke adı büyük harfle başlar; ayrı sözcükler birleştirilmez."}, {"id": "5-2-buyuk-harf-5", "prompt": "Normal cümle yazımında özel ad kuralına göre aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Minnoşbahçede", "Minnoş bahçede", "minnoş bahçede"], "answer": "Minnoş bahçede", "explanation": "Kişi, saygı sözü, hayvan özel adı veya ülke adı büyük harfle başlar; ayrı sözcükler birleştirilmez."}, {"id": "5-2-buyuk-harf-6", "prompt": "Normal cümle yazımında özel ad kuralına göre aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Karabaş uyuyor", "karabaş uyuyor", "Karabaşuyuyor"], "answer": "Karabaş uyuyor", "explanation": "Kişi, saygı sözü, hayvan özel adı veya ülke adı büyük harfle başlar; ayrı sözcükler birleştirilmez."}, {"id": "5-2-buyuk-harf-7", "prompt": "Normal cümle yazımında özel ad kuralına göre aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["türkiye haritası", "Türkiyeharitası", "Türkiye haritası"], "answer": "Türkiye haritası", "explanation": "Kişi, saygı sözü, hayvan özel adı veya ülke adı büyük harfle başlar; ayrı sözcükler birleştirilmez."}, {"id": "5-2-buyuk-harf-8", "prompt": "Normal cümle yazımında özel ad kuralına göre aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Japonyagezisi", "Japonya gezisi", "japonya gezisi"], "answer": "Japonya gezisi", "explanation": "Kişi, saygı sözü, hayvan özel adı veya ülke adı büyük harfle başlar; ayrı sözcükler birleştirilmez."}, {"id": "5-2-buyuk-harf-9", "prompt": "Normal cümle yazımında özel ad kuralına göre aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Zeynep''in sorusu", "zeynep''in sorusu", "Zeynep’insorusu"], "answer": "Zeynep''in sorusu", "explanation": "Kişi, saygı sözü, hayvan özel adı veya ülke adı büyük harfle başlar; ayrı sözcükler birleştirilmez."}, {"id": "5-2-buyuk-harf-10", "prompt": "Normal cümle yazımında özel ad kuralına göre aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Ece öğretmen", "ece Öğretmen", "Ece Öğretmen"], "answer": "Ece Öğretmen", "explanation": "Kişi, saygı sözü, hayvan özel adı veya ülke adı büyük harfle başlar; ayrı sözcükler birleştirilmez."}]'::jsonb),
('5-2-virgul','[{"id": "5-2-virgul-1", "prompt": "Virgülün gerekli olduğu yerler gösterilecekse aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Çantamda kitap kalem ve silgi var.", "Çantamda kitap; kalem ve silgi var.", "Çantamda kitap, kalem ve silgi var."], "answer": "Çantamda kitap, kalem ve silgi var.", "explanation": "Virgül bu örnekte sıralama, hitap, tekrar veya ondalık ayırma görevindedir; noktalı virgül aynı görevin yerine gelişigüzel kullanılmaz."}, {"id": "5-2-virgul-2", "prompt": "Virgülün gerekli olduğu yerler gösterilecekse aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Panoya resim: belge ve harita astık.", "Panoya resim, belge ve harita astık.", "Panoya resim belge ve harita astık."], "answer": "Panoya resim, belge ve harita astık.", "explanation": "Virgül bu örnekte sıralama, hitap, tekrar veya ondalık ayırma görevindedir; noktalı virgül aynı görevin yerine gelişigüzel kullanılmaz."}, {"id": "5-2-virgul-3", "prompt": "Virgülün gerekli olduğu yerler gösterilecekse aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Deniz, sorunu yeniden okur musun?", "Deniz sorunu yeniden okur musun?", "Deniz; sorunu yeniden okur musun?"], "answer": "Deniz, sorunu yeniden okur musun?", "explanation": "Virgül bu örnekte sıralama, hitap, tekrar veya ondalık ayırma görevindedir; noktalı virgül aynı görevin yerine gelişigüzel kullanılmaz."}, {"id": "5-2-virgul-4", "prompt": "Virgülün gerekli olduğu yerler gösterilecekse aşağıdaki seçeneklerden hangisi doğru yazılmıştır?", "choices": ["Sevgili arkadaşlar sergimize hoş geldiniz.", "Sevgili arkadaşlar; sergimize hoş geldiniz.", "Sevgili arkadaşlar, sergimize hoş geldiniz."], "answer": "Sevgili arkadaşlar, sergimize hoş geldiniz.", "explanation": "Virgül bu örnekte sıralama, hitap, tekrar veya ondalık ayırma görevindedir; noktalı virgül aynı görevin yerine gelişigüzel kullanılmaz."}, {"id": "5-2-virgul-5", "prompt": "Virgülün gerekli olduğu yerler gösterilecekse aşağıdaki se