('5-2-soru-isareti','[{"id": "5-2-soru-isareti-1", "prompt": "Aşağıdaki sözlerden hangisi doğrudan soru bildirir ve sonuna soru işareti gerektirir? (1. durum)", "choices": ["Sergi ne zaman açılacak", "Sergi bugün açılacak", "Sergi çok ilgi gördü"], "answer": "Sergi ne zaman açılacak", "explanation": "Doğru seçenek karşı taraftan bilgi istemektedir; diğerleri bilgi verir veya öneride bulunur."}, {"id": "5-2-soru-isareti-2", "prompt": "Aşağıdaki sözlerden hangisi doğrudan soru bildirir ve sonuna soru işareti gerektirir? (2. durum)", "choices": ["Defteri Deniz getirdi", "Defter masada duruyor", "Defteri kim getirdi"], "answer": "Defteri kim getirdi", "explanation": "Doğru seçenek karşı taraftan bilgi istemektedir; diğerleri bilgi verir veya öneride bulunur."}, {"id": "5-2-soru-isareti-3", "prompt": "Aşağıdaki sözlerden hangisi doğrudan soru bildirir ve sonuna soru işareti gerektirir? (3. durum)", "choices": ["Bu belgeyi dikkatle inceledik", "Bu belgeyi nerede buldunuz", "Bu belgeyi arşivde bulduk"], "answer": "Bu belgeyi nerede buldunuz", "explanation": "Doğru seçenek karşı taraftan bilgi istemektedir; diğerleri bilgi verir veya öneride bulunur."}, {"id": "5-2-soru-isareti-4", "prompt": "Aşağıdaki sözlerden hangisi doğrudan soru bildirir ve sonuna soru işareti gerektirir? (4. durum)", "choices": ["Panoyu nasıl hazırladınız", "Panoyu birlikte hazırladık", "Panoyu koridora astık"], "answer": "Panoyu nasıl hazırladınız", "explanation": "Doğru seçenek karşı taraftan bilgi istemektedir; diğerleri bilgi verir veya öneride bulunur."}, {"id": "5-2-soru-isareti-5", "prompt": "Aşağıdaki sözlerden hangisi doğrudan soru bildirir ve sonuna soru işareti gerektirir? (5. durum)", "choices": ["Toplantı birazdan başlayacak", "Toplantı için hazırlık yaptık", "Toplantı saat kaçta başlayacak"], "answer": "Toplantı saat kaçta başlayacak", "explanation": "Doğru seçenek karşı taraftan bilgi istemektedir; diğerleri bilgi verir veya öneride bulunur."}, {"id": "5-2-soru-isareti-6", "prompt": "Aşağıdaki sözlerden hangisi doğrudan soru bildirir ve sonuna soru işareti gerektirir? (6. durum)", "choices": ["Mektup dün okundu", "Mektup kime yazılmış", "Mektup arkadaşına yazılmış"], "answer": "Mektup kime yazılmış", "explanation": "Doğru seçenek karşı taraftan bilgi istemektedir; diğerleri bilgi verir veya öneride bulunur."}, {"id": "5-2-soru-isareti-7", "prompt": "Aşağıdaki sözlerden hangisi doğrudan soru bildirir ve sonuna soru işareti gerektirir? (7. durum)", "choices": ["Kaynağı kontrol ettin mi", "Kaynağı kontrol ettim", "Kaynağı deftere yazdım"], "answer": "Kaynağı kontrol ettin mi", "explanation": "Doğru seçenek karşı taraftan bilgi istemektedir; diğerleri bilgi verir veya öneride bulunur."}, {"id": "5-2-soru-isareti-8", "prompt": "Aşağıdaki sözlerden hangisi doğrudan soru bildirir ve sonuna soru işareti gerektirir? (8. durum)", "choices": ["Bu kitap benim", "Bu kitap yeni basılmış", "Bu kitap senin mi"], "answer": "Bu kitap senin mi", "explanation": "Doğru seçenek karşı taraftan bilgi istemektedir; diğerleri bilgi verir veya öneride bulunur."}, {"id": "5-2-soru-isareti-9", "prompt": "Aşağıdaki sözlerden hangisi doğrudan soru bildirir ve sonuna soru işareti gerektirir? (9. durum)", "choices": ["Öğrenciler hazırlandı", "Kaç öğrenci sunum yapacak", "Üç öğrenci sunum yapacak"], "answer": "Kaç öğrenci sunum yapacak", "explanation": "Doğru seçenek karşı taraftan bilgi istemektedir; diğerleri bilgi verir veya öneride bulunur."}, {"id": "5-2-soru-isareti-10", "prompt": "Aşağıdaki sözlerden hangisi doğrudan soru bildirir ve sonuna soru işareti gerektirir? (10. durum)", "choices": ["Hangi soruyla başlayalım", "İlk soruyla başlayalım", "İlk soru panoda duruyor"], "answer": "Hangi soruyla başlayalım", "explanation": "Doğru seçenek karşı taraftan bilgi istemektedir; diğerleri bilgi verir veya öneride bulunur."}]'::jsonb),
('5-2-ismi-niteleyen','[{"id": "5-2-ismi-niteleyen-1", "prompt": "“Kırmızı çanta sandalyenin yanında duruyor.” cümlesinde “Kırmızı” hangi ismi niteler veya belirtir?", "choices": ["yan", "çanta", "sandalye"], "answer": "çanta", "explanation": "“Kırmızı”, bu cümlede “çanta” ismi hakkında özellik veya belirleme bilgisi verir."}, {"id": "5-2-ismi-niteleyen-2", "prompt": "“Üç öğrenci kapının önünde bekliyor.” cümlesinde “Üç” hangi ismi niteler veya belirtir?", "choices": ["öğrenci", "kapı", "ön"], "answer": "öğrenci", "explanation": "“Üç”, bu cümlede “öğrenci” ismi hakkında özellik veya belirleme bilgisi verir."}, {"id": "5-2-ismi-niteleyen-3", "prompt": "“Bu kitap masanın üstündeydi.” cümlesinde “Bu” hangi ismi niteler veya belirtir?", "choices": ["masa", "üst", "kitap"], "answer": "kitap", "explanation": "“Bu”, bu cümlede “kitap” ismi hakkında özellik veya belirleme bilgisi verir."}, {"id": "5-2-ismi-niteleyen-4", "prompt": "“Birkaç konuk sergiyi gezdi.” cümlesinde “Birkaç” hangi ismi niteler veya belirtir?", "choices": ["gezi", "konuk", "sergi"], "answer": "konuk", "explanation": "“Birkaç”, bu cümlede “konuk” ismi hakkında özellik veya belirleme bilgisi verir."}, {"id": "5-2-ismi-niteleyen-5", "prompt": "“Eski fotoğraf defterin içindeydi.” cümlesinde “Eski” hangi ismi niteler veya belirtir?", "choices": ["fotoğraf", "defter", "iç"], "answer": "fotoğraf", "explanation": "“Eski”, bu cümlede “fotoğraf” ismi hakkında özellik veya belirleme bilgisi verir."}, {"id": "5-2-ismi-niteleyen-6", "prompt": "“Uzun mektup çekmeceye kondu.” cümlesinde “Uzun” hangi ismi niteler veya belirtir?", "choices": ["çekmece", "konu", "mektup"], "answer": "mektup", "explanation": "“Uzun”, bu cümlede “mektup” ismi hakkında özellik veya belirleme bilgisi verir."}, {"id": "5-2-ismi-niteleyen-7", "prompt": "“İki pano koridora asıldı.” cümlesinde “İki” hangi ismi niteler veya belirtir?", "choices": ["askı", "pano", "koridor"], "answer": "pano", "explanation": "“İki”, bu cümlede “pano” ismi hakkında özellik veya belirleme bilgisi verir."}, {"id": "5-2-ismi-niteleyen-8", "prompt": "“Küçük çocuk bahçede oynuyor.” cümlesinde “Küçük” hangi ismi niteler veya belirtir?", "choices": ["çocuk", "bahçe", "oyun"], "answer": "çocuk", "explanation": "“Küçük”, bu cümlede “çocuk” ismi hakkında özellik veya belirleme bilgisi verir."}, {"id": "5-2-ismi-niteleyen-9", "prompt": "“Her takım sorusunu hazırladı.” cümlesinde “Her” hangi ismi niteler veya belirtir?", "choices": ["soru", "hazırlık", "takım"], "answer": "takım", "explanation": "“Her”, bu cümlede “takım” ismi hakkında özellik veya belirleme bilgisi verir."}, {"id": "5-2-ismi-niteleyen-10", "prompt": "“Parlak yıldız gökyüzünde göründü.” cümlesinde “Parlak” hangi ismi niteler veya belirtir?", "choices": ["görünüm", "yıldız", "gökyüzü"], "answer": "yıldız", "explanation": "“Parlak”, bu cümlede “yıldız” ismi hakkında özellik veya belirleme bilgisi verir."}]'::jsonb),
('5-2-sifat-fiil','[{"id": "5-2-sifat-fiil-1", "prompt": "“Bahçede gülen çocuk vardı.” cümlesinde eylemden türeyerek bir ismi betimleyen sözcük hangisidir?", "choices": ["gülen", "çocuk", "bahçe"], "answer": "gülen", "explanation": "“gülen” bir hareket veya iş bilgisini “çocuk” ismine özellik olarak ekler."}, {"id": "5-2-sifat-fiil-2", "prompt": "“Derede akan su berraktı.” cümlesinde eylemden türeyerek bir ismi betimleyen sözcük hangisidir?", "choices": ["su", "dere", "akan"], "answer": "akan", "explanation": "“akan” bir hareket veya iş bilgisini “su” ismine özellik olarak ekler."}, {"id": "5-2-sifat-fiil-3", "prompt": "“Okunacak kitap raftaydı.” cümlesinde eylemden türeyerek bir ismi betimleyen sözcük hangisidir?", "choices": ["raf", "Okunacak", "kitap"], "answer": "Okunacak", "explanation": "“Okunacak” bir hareket veya iş bilgisini “kitap” ismine özellik olarak ekler."}, {"id": "5-2-sifat-fiil-4", "prompt": "“Yazılmış mektup çekmecedeydi.” cümlesinde eylemden türeyerek bir ismi betimleyen sözcük hangisidir?", "choices": ["Yazılmış", "mektup", "çekmece"], "answer": "Yazılmış", "explanation": "“Yazılmış” bir hareket veya iş bilgisini “mektup” ismine özellik olarak ekler."}, {"id": "5-2-sifat-fiil-5", "prompt": "“Açılan kapı bahçeye bakıyordu.” cümlesinde eylemden türeyerek bir ismi betimleyen sözcük hangisidir?", "choices": ["kapı", "bahçe", "Açılan"], "answer": "Açılan", "explanation": "“Açılan” bir hareket veya iş bilgisini “kapı” ismine özellik olarak ekler."}, {"id": "5-2-sifat-fiil-6", "prompt": "“Büyüyen ağaç bahçeyi gölgeliyordu.” cümlesinde eylemden türeyerek bir ismi betimleyen sözcük hangisidir?", "choices": ["bahçe", "Büyüyen", "ağaç"], "answer": "Büyüyen", "explanation": "“Büyüyen” bir hareket veya iş bilgisini “ağaç” ismine özellik olarak ekler."}, {"id": "5-2-sifat-fiil-7", "prompt": "“Bekleyen konuk salondaydı.” cümlesinde eylemden türeyerek bir ismi betimleyen sözcük hangisidir?", "choices": ["Bekleyen", "konuk", "salon"], "answer": "Bekleyen", "explanation": "“Bekleyen” bir hareket veya iş bilgisini “konuk” ismine özellik olarak ekler."}, {"id": "5-2-sifat-fiil-8", "prompt": "“Sönen ışık koridoru kararttı.” cümlesinde eylemden türeyerek bir ismi betimleyen sözcük hangisidir?", "choices": ["ışık", "koridor", "Sönen"], "answer": "Sönen", "explanation": "“Sönen” bir hareket veya iş bilgisini “ışık” ismine özellik olarak ekler."}, {"id": "5-2-sifat-fiil-9", "prompt": "“Düşen yaprak masadaydı.” cümlesinde eylemden türeyerek bir ismi betimleyen sözcük hangisidir?", "choices": ["masa", "Düşen", "yaprak"], "answer": "Düşen", "explanation": "“Düşen” bir hareket veya iş bilgisini “yaprak” ismine özellik olarak ekler."}, {"id": "5-2-sifat-fiil-10", "prompt": "“Çözülen bulmaca defterdeydi.” cümlesinde eylemden türeyerek bir ismi betimleyen sözcük hangisidir?", "choices": ["Çözülen", "bulmaca", "defter"], "answer": "Çözülen", "explanation": "“Çözülen” bir hareket veya iş bilgisini “bulmaca” ismine özellik olarak ekler."}]'::jsonb),
('5-2-ekleme','[{"id": "5-2-ekleme-1", "prompt": "“Kitapları düzenledik, ayrıca rafları sildik.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["özetleme", "ekleme", "karşıtlık"], "answer": "ekleme", "explanation": "Cümledeki ifade ekleme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-2-ekleme-2", "prompt": "“Panoyu hazırladık, üstelik bir soru kutusu ekledik.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["ekleme", "karşıtlık", "özetleme"], "answer": "ekleme", "explanation": "Cümledeki ifade ekleme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-2-ekleme-3", "prompt": "“Araştırdık, hatta küçük bir sergi açtık.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["karşıtlık", "özetleme", "ekleme"], "answer": "ekleme", "explanation": "Cümledeki ifade ekleme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-2-ekleme-4", "prompt": "“Hem metni okuduk hem kaynakları not ettik.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["özetleme", "ekleme", "karşıtlık"], "answer": "ekleme", "explanation": "Cümledeki ifade ekleme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-2-ekleme-5", "prompt": "“Fotoğrafları ve belgeleri birlikte inceledik.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["ekleme", "karşıtlık", "özetleme"], "answer": "ekleme", "explanation": "Cümledeki ifade ekleme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-2-ekleme-6", "prompt": "“Müzeyi gezdik, bunun dışında kütüphaneye de uğradık.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["karşıtlık", "özetleme", "ekleme"], "answer": "ekleme", "explanation": "Cümledeki ifade ekleme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-2-ekleme-7", "prompt": "“Kaynağın adını yazdım, bir de tarihini ekle