('5-3-unlem','[{"id": "5-3-unlem-1", "prompt": "“Yaşasın, gösterimiz çok güzel geçti!” sözünde ünlem işareti hangi işlevi öne çıkarır?", "choices": ["şüphe", "sevinç", "üzüntü"], "answer": "sevinç", "explanation": "Cümlenin anlamı sevinç bildirir; ünlemin işlevini yalnızca işarete değil söze bakarak belirleriz."}, {"id": "5-3-unlem-2", "prompt": "“Eyvah, defterimi evde unuttum!” sözünde ünlem işareti hangi işlevi öne çıkarır?", "choices": ["telaş", "memnuniyet", "küçümseme"], "answer": "telaş", "explanation": "Cümlenin anlamı telaş bildirir; ünlemin işlevini yalnızca işarete değil söze bakarak belirleriz."}, {"id": "5-3-unlem-3", "prompt": "“Dikkat, zemin kaygan!” sözünde ünlem işareti hangi işlevi öne çıkarır?", "choices": ["özlem", "pişmanlık", "uyarı"], "answer": "uyarı", "explanation": "Cümlenin anlamı uyarı bildirir; ünlemin işlevini yalnızca işarete değil söze bakarak belirleriz."}, {"id": "5-3-unlem-4", "prompt": "“Vay, ne büyük bir kütüphane!” sözünde ünlem işareti hangi işlevi öne çıkarır?", "choices": ["üzüntü", "şaşırma", "emir"], "answer": "şaşırma", "explanation": "Cümlenin anlamı şaşırma bildirir; ünlemin işlevini yalnızca işarete değil söze bakarak belirleriz."}, {"id": "5-3-unlem-5", "prompt": "“Hey, buraya bak!” sözünde ünlem işareti hangi işlevi öne çıkarır?", "choices": ["seslenme", "özetleme", "tahmin"], "answer": "seslenme", "explanation": "Cümlenin anlamı seslenme bildirir; ünlemin işlevini yalnızca işarete değil söze bakarak belirleriz."}, {"id": "5-3-unlem-6", "prompt": "“Ah, eski arkadaşımı çok özledim!” sözünde ünlem işareti hangi işlevi öne çıkarır?", "choices": ["küçümseme", "sevinç", "özlem"], "answer": "özlem", "explanation": "Cümlenin anlamı özlem bildirir; ünlemin işlevini yalnızca işarete değil söze bakarak belirleriz."}, {"id": "5-3-unlem-7", "prompt": "“Ne güzel, hepimiz katılabiliyoruz!” sözünde ünlem işareti hangi işlevi öne çıkarır?", "choices": ["pişmanlık", "memnuniyet", "şüphe"], "answer": "memnuniyet", "explanation": "Cümlen