('5-4-zamir','[{"id": "5-4-zamir-1", "prompt": "“Zeynep kilimi inceledi. Zeynep not aldı.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Biz", "O", "Onlar"], "answer": "O", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “O” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-2", "prompt": "“Çocuklar sofrayı kurdu. Çocuklar konukları karşıladı.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Onlar", "O", "Ben"], "answer": "Onlar", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “Onlar” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-3", "prompt": "“Dedem mektubu okudu. Dedem gülümsedi.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Onlar", "Siz", "O"], "answer": "O", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “O” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-4", "prompt": "“Komşular bahçeyi temizledi. Komşular dinlendi.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Sen", "Onlar", "O"], "answer": "Onlar", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “Onlar” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-5", "prompt": "“Ece masalı dinledi. Ece bir soru sordu.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["O", "Onlar", "Biz"], "answer": "O", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “O” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-6", "prompt": "“Konuklar sergiyi gezdi. Konuklar teşekkür etti.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Ben", "O", "Onlar"], "answer": "Onlar", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “Onlar” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-7", "prompt": "“Usta çömleği yaptı. Usta onu kurumaya bıraktı.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Biz", "O", "Onlar"], "answer": "O", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “O” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-8", "prompt": "“Öğrenciler not tuttu. Öğrenciler özet yazdı.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Onlar", "O", "Sen"], "answer": "Onlar", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “Onlar” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-9", "prompt": "“Nermin Hanım önerisini anlattı. Nermin Hanım sırayı bekledi.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Onlar", "Siz", "O"], "answer": "O", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “O” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-10", "prompt": "“Arkadaşlar oyunu öğrendi. Arkadaşlar kuralları yazdı.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Ben", "Onlar", "O"], "answer": "Onlar", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “Onlar” korur; gönderme önceki cümleden anlaşılır."}]'::jsonb),
('5-5-zaman-baglac','[{"id": "5-5-zaman-baglac-1", "prompt": "“Önce duyuruyu okuduk, sonra sorularımızı yazdık.” cümlesinde “Önce” hangi zaman ilişkisini kurar?", "choices": ["eş zamanlılık", "öncelik", "sonralık"], "answer": "öncelik", "explanation": "“Önce” burada öncelik bildirerek olayları zaman bakımından ilişkilendirir."}, {"id": "5-5-zaman-baglac-2", "prompt": "“Sunum bitti, ardından sorular başladı.” cümlesinde “ardından” hangi zaman ilişkisini kurar?", "choices": ["sonralık", "öncelik", "eş zamanlılık"], "answer": "sonralık", "explanation": "“ardından” burada sonralık bildirerek olayları zaman bakımından ilişkilendirir."}, {"id": "5-5-zaman-baglac-3", "prompt": "“Ben yazarken bu sırada arkadaşım okudu.” cümlesinde “bu sırada” hangi zaman ilişkisini kurar?", "choices": ["öncelik", "sonralık", "eş zamanlılık"], "answer": "eş zamanlılık", "explanation": "“bu sırada” burada eş zamanlılık bildirerek olayları zaman bakımından ilişkilendirir."}, {"id": "5-5-zaman-baglac-4", "prompt": "“İlk olarak buluşmanın yerini belirledik.” cümlesinde “İlk olarak” hangi zaman ilişkisini kurar?", "choices": ["eş zamanlılık", "öncelik", "sonralık"], "answer": "öncelik", "explanation": "“İlk olarak” burada öncelik bildirerek olayları zaman bakımından ilişkilendirir."}, {"id": "5-5-zaman-baglac-5", "prompt": "“Öncelikle metnin amacını düşündük.” cümlesinde “Öncelikle” hangi zaman ilişkisini kurar?", "choices": ["öncelik", "sonralık", "eş zamanlılık"], "answer": "öncelik", "explanation": "“Öncelikle” burada öncelik bildirerek olayları zaman bakımından ilişkilendirir."}, {"id": "5-5-zaman-baglac-6", "prompt": "“Notları aldık, daha sonra özeti hazırladık.” cümlesinde “daha sonra” hangi zaman ilişkisini kurar?", "choices": ["öncelik", "eş zamanlılık", "sonralık"], "answer": "sonralık", "explanation": "“daha sonra” burada sonralık bildirerek olayları zaman bakımından ilişkilendirir."}, {"id": "5-5-zaman-baglac-7", "prompt": "“Son olarak bütün duyuruyu kontrol ettik.” cümlesinde “Son olarak” hangi zaman ilişkisini kurar?", "choices": ["eş zamanlılık", "sonralık", "öncelik"], "answer": "sonralık", "explanation": "“Son olarak” burada sonralık bildirerek olayları zaman bakımından ilişkilendirir."}, {"id": "5-5-zaman-baglac-8", "prompt": "“Aynı anda iki grup farklı afişleri inceledi.” cümlesinde “Aynı anda” hangi zaman ilişkisini kurar?", "choices": ["eş zamanlılık", "öncelik", "sonralık"], "answer": "eş zamanlılık", "explanation": "“Aynı anda” burada eş zamanlılık bildirerek olayları zaman bakımından ilişkilendirir."}, {"id": "5-5-zaman-baglac-9", "prompt": "“Bir yandan dinledim, bir yandan not tuttum.” cümlesinde “Bir yandan ... bir yandan” hangi zaman ilişkisini kurar?", "choices": ["öncelik", "sonralık", "eş zamanlılık"], "answer": "eş zamanlılık", "explanation": "“Bir yandan ... bir yandan” burada eş zamanlılık bildirerek olayları zaman bakımından ilişkilendirir."}, {"id": "5-5-zaman-baglac-10", "prompt": "“Önce soruyu anladık, en sonunda cevap verdik.” cümlesinde “en sonunda” hangi zaman ilişkisini kurar?", "choices": ["eş zamanlılık", "sonralık", "öncelik"], "answer": "sonralık", "explanation": "“en sonunda” burada sonralık bildirerek olayları zaman bakımından ilişkilendirir."}]'::jsonb),
