('5-5-anlam-butunlugu','[{"id": "5-5-anlam-butunlugu-1", "prompt": "“kesinlikle belki gelecek” sözündeki çelişen kesinlik veya miktar ifadeleri giderildiğinde hangi seçenek tutarlı olur?", "choices": ["Belki kesinlikle gelecek.", "Kesinlikle gelecek.", "Kesinlikle belki gelecek."], "answer": "Kesinlikle gelecek.", "explanation": "Kesinlik, belirsizlik veya miktar bakımından çatışan sözlerden biri çıkarılınca yargı tutarlı hâle gelir."}, {"id": "5-5-anlam-butunlugu-2", "prompt": "“tam olarak yaklaşık on dakika” sözündeki çelişen kesinlik veya miktar ifadeleri giderildiğinde hangi seçenek tutarlı olur?", "choices": ["Yaklaşık on dakika.", "Tam olarak yaklaşık on dakika.", "Yaklaşık tam olarak on dakika."], "answer": "Yaklaşık on dakika.", "explanation": "Kesinlik, belirsizlik veya miktar bakımından çatışan sözlerden biri çıkarılınca yargı tutarlı hâle gelir."}, {"id": "5-5-anlam-butunlugu-3", "prompt": "“eminim galiba duydu” sözündeki çelişen kesinlik veya miktar ifadeleri giderildiğinde hangi seçenek tutarlı olur?", "choices": ["Eminim galiba duydu.", "Galiba eminim duydu.", "Eminim duydu."], "answer": "Eminim duydu.", "explanation": "Kesinlik, belirsizlik veya miktar bakımından çatışan sözlerden biri çıkarılınca yargı tutarlı hâle gelir."}, {"id": "5-5-anlam-butunlugu-4", "prompt": "“mutlaka belki katılır” sözündeki çelişen kesinlik veya miktar ifadeleri giderildiğinde hangi seçenek tutarlı olur?", "choices": ["Belki mutlaka katılır.", "Belki katılır.", "Mutlaka belki katılır."], "answer": "Belki katılır.", "explanation": "Kesinlik, belirsizlik veya miktar bakımından çatışan sözlerden biri çıkarılınca yargı tutarlı hâle gelir."}, {"id": "5-5-anlam-butunlugu-5", "prompt": "“tamamen kısmen bitti” sözündeki çelişen kesinlik veya miktar ifadeleri giderildiğinde hangi seçenek tutarlı olur?", "choices": ["Kısmen bitti.", "Tamamen kısmen bitti.", "Kısmen tamamen bitti."], "answer": "Kısmen bitti.", "explanation": "Kesinlik, belirsizlik veya miktar bakımından çatışan sözlerden biri çıkarılınca yargı tutarlı hâle gelir."}, {"id": "5-5-anlam-butunlugu-6", "prompt": "“kesin olarak herhâlde açılır” sözündeki çelişen kesinlik veya miktar ifadeleri giderildiğinde hangi seçenek tutarlı olur?", "choices": ["Kesin olarak herhâlde açılır.", "Herhâlde kesin olarak açılır.", "Herhâlde açılır."], "answer": "Herhâlde açılır.", "explanation": "Kesinlik, belirsizlik veya miktar bakımından çatışan sözlerden biri çıkarılınca yargı tutarlı hâle gelir."}, {"id": "5-5-anlam-butunlugu-7", "prompt": "“tümüyle biraz değişti” sözündeki çelişen kesinlik veya miktar ifadeleri giderildiğinde hangi seçenek tutarlı olur?", "choices": ["Biraz tümüyle değişti.", "Biraz değişti.", "Tümüyle biraz değişti."], "answer": "Biraz değişti.", "explanation": "Kesinlik, belirsizlik veya miktar bakımından çatışan sözlerden biri çıkarılınca yargı tutarlı hâle gelir."}, {"id": "5-5-anlam-butunlugu-8", "prompt": "“tam tamına aşağı yukarı beş sayfa” sözündeki çelişen kesinlik veya miktar ifadeleri giderildiğinde hangi seçenek tutarlı olur?", "choices": ["Aşağı yukarı beş sayfa.", "Tam tamına aşağı yukarı beş sayfa.", "Aşağı yukarı tam tamına beş sayfa."], "answer": "Aşağı yukarı beş sayfa.", "explanation": "Kesinlik, belirsizlik veya miktar bakımından çatışan sözlerden biri çıkarılınca yargı tutarlı hâle gelir."}, {"id": "5-5-anlam-butunlugu-9", "prompt": "“kuşkusuz sanırım biliyor” sözündeki çelişen kesinlik veya miktar ifadeleri giderildiğinde hangi seçenek tutarlı olur?", "choices": ["Kuşkusuz sanırım biliyor.", "Sanırım kuşkusuz biliyor.", "Sanırım biliyor."], "answer": "Sanırım biliyor.", "explanation": "Kesinlik, belirsizlik veya miktar bakımından çatışan sözlerden biri çıkarılınca yargı tutarlı hâle gelir."}, {"id": "5-5-anlam-butunlugu-10", "prompt": "“kesinlikle muhtemelen bekler” sözündeki çelişen kesinlik veya miktar ifadeleri giderildiğinde hangi seçenek tutarlı olur?", "choices": ["Muhtemelen kesinlikle bekler.", "Muhtemelen bekler.", "Kesinlikle muhtemelen bekler."], "answer": "Muhtemelen bekler.", "explanation": "Kesinlik, belirsizlik veya miktar bakımından çatışan sözlerden biri çıkarılınca yargı tutarlı hâle gelir."}]'::jsonb),
('5-5-yeniden-kurma','[{"id": "5-5-yeniden-kurma-1", "prompt": "“Duru duyuruyu arkadaşları daha iyi anlasın diye yeniden yazdı.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Duru, duyuruyu hiç kimse okumasın diye sakladı.", "Duru, arkadaşları anladığı için duyuruyu sildi.", "Duru, duyuruyu daha anlaşılır kılmak için tekrar yazdı."], "answer": "Duru, duyuruyu daha anlaşılır kılmak için tekrar yazdı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-2", "prompt": "“Toplantıdan önce herkes sorusunu hazırladı.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Toplantıda hiç soru hazırlanmadı.", "Herkes, toplantı başlamadan sorusunu belirledi.", "Herkes sorusunu toplantı bittikten sonra hazırladı."], "answer": "Herkes, toplantı başlamadan sorusunu belirledi.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-3", "prompt": "“Elif arkadaşının sözünü bitirmesini bekledi.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Elif, arkadaşı konuşmasını tamamlayınca söz aldı.", "Elif, arkadaşı bitirmeden sözünü kesti.", "Elif, arkadaşının hiç konuşmamasını istedi."], "answer": "Elif, arkadaşı konuşmasını tamamlayınca söz aldı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-4", "prompt": "“Saat değiştiği için duyuru güncellendi.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Saat aynı kaldığı için duyuru kaldırıldı.", "Duyurunun değişmesi saati geri aldı.", "Duyuru, değişen saate göre yeniden düzenlendi."], "answer": "Duyuru, değişen saate göre yeniden düzenlendi.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-5", "prompt": "“Mert fikrini bir örnekle açıkladı.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Mert, hiçbir örnek vermeden konuştu.", "Mert, düşüncesini anlatırken örnek kullandı.", "Mert, fikrini söylemekten vazgeçti."], "answer": "Mert, düşüncesini anlatırken örnek kullandı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-6", "prompt": "“Herkesin katılabileceği bir zaman seçildi.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Buluşma için herkesin uygun olduğu zaman belirlendi.", "Yalnızca bir kişinin katılacağı zaman seçildi.", "Hiç kimsenin uygun olmadığı zaman belirlendi."], "answer": "Buluşma için herkesin uygun olduğu zaman belirlendi.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-7", "prompt": "“Öğrenciler metni okuduktan sonra özetledi.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Öğrenciler metni okumadan özetledi.", "Öğrenciler özeti okuduktan sonra metni yazdı.", "Öğrenciler önce metni okudu, ardından özetini çıkardı."], "answer": "Öğrenciler önce metni okudu, ardından özetini çıkardı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-8", "prompt": "“Yanlış bilgi yayılmasın diye eski not kaldırıldı.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Eski not doğru olduğu için hemen dağıtıldı.", "Eski not, yanlış bilginin yayılmasını önlemek için alındı.", "Eski not, yanlış bilgi yayılsın diye çoğaltıldı."], "answer": "Eski not, yanlış bilginin yayılmasını önlemek için alındı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-9", "prompt": "“Arkadaşım yardım istediğinde onu dinledim.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Yardım talep eden arkadaşıma kulak verdim.", "Arkadaşım yardım isteyince onu susturdum.", "Yardım istemeyen arkadaşımdan uzaklaştım."], "answer": "Yardım talep eden arkadaşıma kulak verdim.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-10", "prompt": "“Grup kararı birlikte değerlendirerek verdi.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Kararı gruptan habersiz biri tek başına verdi.", "Grup hiçbir değerlendirme yapmadan dağıldı.", "Grup, karara ortak bir değerlendirmeyle ulaştı."], "answer": "Grup, karara ortak bir değerlendirmeyle ulaştı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}]'::jsonb),
('5-6-ornek','[{"id": "5-6-ornek-1", "prompt": "“Farklı etkinlikler seçebiliriz; söz gelimi kelime oyunu oynayabiliriz.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["örneklendirme", "karşıtlık", "amaç"], "answer": "örneklendirme", "explanation": "Cümledeki ifade örneklendirme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-6-ornek-2", "prompt": "“Bazı metinler bilgi verir; örneğin bir ürün etiketi böyledir.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["karşıtlık", "amaç", "örneklendirme"], "answer": "örneklendirme", "explanation": "Cümledeki ifade örneklendirme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-6-ornek-3", "prompt": "“Güvenilirlik için bilgiler kontrol edilir; mesela kaynağın adı araştırılır.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["amaç", "örneklendirme", "karşıtlık"], "answer": "örneklendirme", "explanation": "Cümledeki ifade örneklendirme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-6-ornek-4", "prompt": "“Bahçede farklı alanlar olabilir; örnek olarak sessiz bir köşe hazırlanabilir.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["örneklendirme", "karşıtlık", "amaç"], "answer": "örneklendirme", "explanation": "Cümledeki ifade örneklendirme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-6-ornek-5", "prompt": "“Gereken bilgileri yazalım; örneğin gün ve saati belirtelim.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["karşıtlık", "amaç", "örneklendirme"], "answer": "örneklendirme", "explanation": "Cümledeki ifade örneklendirme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-6-ornek-6", "prompt": "“Kaynakları karşılaştıralım; söz gelimi iki kurumun yazısını inceleyelim.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["amaç", "örneklendirme", "karşıtlık"], "answer": "örneklendirme", "explanation": "Cümledeki ifade örneklendirme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-6-ornek-7", "prompt": "“Katılımı kolaylaştıralım; mesela kuralları büyük yazalım.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["örneklendirme", "karşıtlık", "amaç"], "answer": "örneklendirme", "explanation": "Cümledeki ifade örneklendirme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-6-ornek-8", "prompt": "“Yeni kelimeleri kullanalım; örneğin kısa bir duyuru yazalım.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["karşıtlık", "amaç", "örneklendirme"], "answer": "örneklendirme", "explanation": "Cümledeki ifade örneklendirme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-6-ornek-9", "prompt": "“Bilgiyi düzenleyebiliriz; örnek verecek olursak bir çizelge yapabiliriz.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["amaç", "örneklendirme", "karşıtlık"], "answer": "örneklendirme", "explanation": "Cümledeki ifade örneklendirme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-6-ornek-10", "prompt": "“Farklı ihtiyaçları gözetelim; söz gelimi oturarak oynanan bir seçenek sunalım.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["örneklendirme", "karşıtlık", "amaç"], "answer": "örneklendirme", "explanation": "Cümledeki ifade örneklendirme anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}]'::jsonb),
('5-6-tekrar','[{"id": "5-6-tekrar-1", "prompt": "Sınıf duyurusunda hangisi doğru yazılmıştır?", "choices": ["Bugün kitap okuduk,", "Bugün kitap okuduk;", "Bugün kitap okuduk."], "answer": "Bugün kitap okuduk.", "explanation": "Tamamlanmış haber cümlesinin sonuna nokta konabilir."}, {"id": "5-6-tekrar-2", "prompt": "Doğrudan sorunun yazımı hangisidir?", "choices": ["Planı kontrol ettin mi,", "Planı kontrol ettin mi?", "Planı kontrol ettin mi."], "answer": "Planı kontrol ettin mi?", "explanation": "Soru ekiyle kurulan doğrudan sorunun sonuna soru işareti konur."}, {"id": "5-6-tekrar-3", "prompt": "Kişi adına gelen ekin doğru yazımı hangisidir?", "choices": ["Selin''in çizelgesi", "Selinin çizelgesi", "Selin in çizelgesi"], "answer": "Selin''in çizelgesi", "explanation": "Özel ada gelen iyelik eki kesmeyle ayrılır."}, {"id": "5-6-tekrar-4", "prompt": "Birden çok kelimeden oluşan sayının doğru yazımı hangisidir?", "choices": ["yirmibeş dakika", "yirmi-beş dakika", "yirmi beş dakika"], "answer": "yirmi beş dakika", "explanation": "Sayıyı oluşturan kelimeler ayrı yazılır."}, {"id": "5-6-tekrar-5", "prompt": "Gerekli virgülün kullanıldığı seçenek hangisidir?", "choices": ["Defter; kitap ve kalem masada.", "Defter, kitap ve kalem masada.", "Defter kitap ve kalem masada."], "answer": "Defter, kitap ve kalem masada.", "explanation": "Eş görevli sıralanan ilk iki ad virgülle ayrılır."}, {"id": "5-6-tekrar-6", "prompt": "Uyarının sonunda hangi işaret uygun kullanılmıştır?", "choices": ["Dikkat, zemin kaygan!", "Dikkat, zemin kaygan,", "Dikkat, zemin kaygan;"], "answer": "Dikkat, zemin kaygan!", "explanation": "Uyarı bildiren söz ünlem işaretiyle bitirilebilir."}, {"id": "5-6-tekrar-7", "prompt": "Normal cümle yazımında yer adı hangisinde doğrudur?", "choices": ["ankara''ya gideceğiz.", "An kara''ya gideceğiz.", "Ankara''ya gideceğiz."], "answer": "Ankara''ya gideceğiz.", "explanation": "Yer adı büyük başlar; yönelme eki kesmeyle ayrılır."}, {"id": "5-6-tekrar-8", "prompt": "Kısaltmanın normal doğru yazımı hangisidir?", "choices": ["meb duyurusu", "MEB duyurusu", "Meb duyurusu"], "answer": "MEB duyurusu", "explanation": "Büyük harfli kurum kısaltması MEB biçimindedir."}, {"id": "5-6-tekrar-9", "prompt": "Heceleri doğru ayrılan kelime hangisidir?", "choices": ["din-len-me", "di-nle-nme", "dinl-en-me"], "answer": "din-len-me", "explanation": "Dinlenme kelimesi üç hecedir; sınırlar din-len-me biçimindedir."}, {"id": "5-6-tekrar-10", "prompt": "Konuşma satırı hangi işaretle doğru başlatılmıştır?", "choices": ["- Önce planı okuyalım.", "/ Önce planı okuyalım.", "— Önce planı okuyalım."], "answer": "— Önce planı okuyalım.", "explanation": "Konuşmanın satır başı uzun çizgiyle gösterilebilir."}]'::jsonb)
